WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget, id) AS latest_rank FROM departments QUALIFY latest_rank = 1) SELECT dept_name, SIZE(COLLECT_SET(location)) AS num_locations, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'HR' THEN 1 END), 0), 2) AS budget_per_hr, SUM(budget) AS total_budget FROM ranked GROUP BY dept_name ORDER BY num_locations NULLS LAST;
